WITH RecentEmployees AS (SELECT *, LAST_DAY(hire_date) AS hire_date_month_end FROM employees WHERE job_title NOT IN ('Manager', 'Engineer', 'Designer') AND email LIKE '%@startup.io'), employees_stats AS (SELECT CASE WHEN salary >= 155000 THEN 'high' WHEN salary >= 46000 THEN 'mid' ELSE 'low' END AS salary_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(job_title))) AS job_title_values FROM RecentEmployees GROUP BY CASE WHEN salary >= 155000 THEN 'high' WHEN salary >= 46000 THEN 'mid' ELSE 'low' END) SELECT * FROM employees_stats ORDER BY job_title_values DESC;
